// Generated lightweight metadata from b30-b39 and b38-more; no math task/model imports.
export const LESSONS = {"gridarea":{"topicId":"mt_6xNmQLzuqm","title":"里面铺了多少","formal":"单位正方形与面积","summary":"一块边长为 1 的正方形占 1 个平方单位。相同方片不重叠、不留空地铺满，块数就是面积；沿外边走一圈是另一种量。","reflection":"相同的 12 块方片换个形状，里面的量和外边的长度都一定不变吗？","batch":"B30"},"areadistrib":{"topicId":"mt_AQo4u7O4sM","title":"一块拆成两块，还是这么多","formal":"面积模型与乘法分配律","summary":"同一块长方形可以切成两块：3×(4+2)=3×4+3×2。切开后每块都保留同一条高，不能只给其中一块乘高。","reflection":"把 13 拆成 10 和 3，为什么两块都要乘 6？","batch":"B30"},"walkperim":{"topicId":"mt_wE7-Gs9ENL","title":"沿着外边走一圈","formal":"周长与边长之和","summary":"周长是沿图形外边走完一圈的长度，单位是厘米或米。面积是里面有多少方片，单位是平方厘米或平方米。","reflection":"沿边走过的长度为什么不按里面的方片数记录？","batch":"B30"},"polyperim":{"topicId":"mt_WtcFrxGOgw","title":"一圈已知，藏着哪条边","formal":"多边形周长与未知边","summary":"周长是各外边长度的和。整圈已知时，先减去已知的各边，就能找到剩下的一条。相同周长可以围出面积不同的长方形。","reflection":"围边都长 24 厘米，为什么不一定铺出同样大的地？","batch":"B30"},"lperim":{"topicId":"mt_n0AlyLQwC9","title":"拐个弯，还是沿外边","formal":"组合直边图形的周长","summary":"沿所有外边走，转弯处也不能漏；内部的分界不是外边。缺少的直边可以由对应的总长减去已知部分得到。","reflection":"拆图时画出的那条线，什么时候不能加进周长？","batch":"B30"},"areaPerim":{"topicId":"mt_MJZA90uc6H","title":"一样大，外边一定一样长吗","formal":"面积与周长的关系","summary":"面积相同的长方形可以一个细长、一个更接近正方形，周长不同；周长相同也可以围出不同面积。不能只由其中一个量断定另一个。","reflection":"4×6 和 2×12 都是 24 平方厘米，为什么围边不同？","batch":"B30"},"rectsplit":{"topicId":"mt_eMtV6tBSJm","title":"把不规则地面拆成几块","formal":"组合直边图形的面积","summary":"把图形拆成不重叠、不遗漏的长方形，各块面积可以相加。切法不止一种，合起来仍要刚好覆盖原来的范围。","reflection":"为什么两块重叠时，直接加面积会多算？","batch":"B30"},"triArea":{"topicId":"mt_ML5t7n2-U8","title":"斜着的，也能移回长方形吗","formal":"三角形与平行四边形的面积","summary":"平行四边形可把一端三角形移到另一端，得到同底同高的长方形；两个全等三角形可拼成平行四边形。高度必须垂直于底，可能落在图形外。","reflection":"为什么斜边长不能直接代替垂直高度？","batch":"B30"},"polyArea":{"topicId":"mt_i2-QaXbyzB","title":"不熟悉的形状，拆开看","formal":"多边形面积的分解与补形","summary":"可以拆成互不重叠的长方形和三角形相加，也可以放进外框后减去外面的角。每部分用自己的底和垂直高度，不能漏掉或重复。","reflection":"同一个梯形，分成三块和补成大长方形，会得到不同面积吗？","batch":"B30"},"circleArea":{"topicId":"mt_svFa6_mjO_","title":"圆边和圆里面，怎样量","formal":"圆周长、圆面积与组合图形","summary":"直径穿过圆心，是半径的两倍。圆周长是 π×直径，面积是 π×半径×半径。使用 3.14 代替 π 时结果是近似值；组合图形内部接缝不算外边。","reflection":"两个半圆合起来时，为什么中间直线不属于整个图形的外边？","batch":"B30"},"prismFormulas":{"topicId":"mt_tAJH5BrpOx","title":"一层的形状，怎样堆成里面","formal":"梯形面积与棱柱、圆柱体积","summary":"梯形可以拆成三角形与长方形，也可以用两条平行边的平均长度乘高。直棱柱的体积是底面积乘垂直长度；圆柱也可用圆的底面积乘高。","reflection":"三角形底面和圆形底面不同，为什么都要看一层有多大？","batch":"B30"},"netSurface":{"topicId":"mt_tegkuJA5gM","title":"把盒子的外面摊开","formal":"展开图与表面积","summary":"立体外表由多个面组成；把各面的面积相加得到表面积。开放的盒子少了上盖；表面积用平方单位，装满里面的体积用立方单位。","reflection":"一张纸包住外面和小方块填满里面，为什么单位不同？","batch":"B30"},"solidSurface":{"topicId":"mt_Sij9ByyHq6","title":"接起来，哪些面藏进去了","formal":"棱柱与组合立体的表面积和体积","summary":"直棱柱体积是底面积乘长；外面包括两个底和侧面。两块立体贴合后，接触的两块面藏在里面，要从分开时的表面积中减去；体积按不重叠的两块相加。","reflection":"两块贴在一起时，体积为什么相加，表面积却不能直接相加？","batch":"B30"},"comparecap":{"topicId":"mt_zkFbMLpu3U","title":"换个杯子，还是这么多吗","formal":"容量与当前水量的比较","summary":"容量是容器装满时能容纳多少，当前水量是现在装了多少。同样的水换一个形状不会变多；不同粗细的容器不能只比液面高低。半满和四分之一满要相对同一个容器的容量。","reflection":"细高杯里的水面更高，就一定有更多水吗？","batch":"B31"},"cupmeasure":{"topicId":"mt_4lp_b5Pzik","title":"用同一杯，量一量","formal":"用单位量容量与液体体积","summary":"把同样满的量杯一次次倒入，记下杯数与单位。对同一容器，量杯越大，所需杯数通常越少；也可以用升和毫升记录。","reflection":"为什么一个壶可以是4大杯，也可以是8小杯？","batch":"B31"},"indirectmass":{"topicId":"mt_bnwHo5wfCD","title":"借一个工具，再比较","formal":"质量与容量的间接比较","summary":"不能直接相比较时，可以借同一件物体或同一容器。若甲比乙重、乙比丙重，甲就比丙重；容量也要用一致的单位比较。","reflection":"不能把苹果和鸡蛋同时放在一起，怎样用木块比较它们？","batch":"B31"},"measureliquid":{"topicId":"mt_-af65bxfdp","title":"先估一估，再看刻度","formal":"质量与液体体积的估计和测量","summary":"读量杯或质量秤时，先看相邻数字差多少，数清间隔，再判断液面或指针。记录带上克、千克、升或毫升；相同单位的量才能直接相加。","reflection":"两条数字之间有5小段时，怎样知道每小段是多少？","batch":"B31"},"fractionvolume":{"topicId":"mt_IlDaxVr60U","title":"小方块变小，盒子有多大","formal":"分数边长的长方体体积","summary":"边长为1/2的立方体占1/8立方单位：长、宽、高三个方向都变小。先数小块和层，再比较小块总体积、长宽高相乘与底面积乘高。","reflection":"边长变成一半时，为什么小方块体积不是一半？","batch":"B31"},"timecompare":{"topicId":"mt_TcG90kS8nu","title":"谁先到，谁用得久","formal":"时刻与时长的比较","summary":"先后看事情发生的时刻，快慢或多久看从开始到结束的时间。结束较晚不一定花得更久，要把起点一起看。","reflection":"两个活动结束的先后，为什么不一定能告诉我们谁用了更久？","batch":"B32"},"eventorder":{"topicId":"mt_-vvVxpOHG2","title":"先发生什么，后来呢","formal":"事件的先后顺序与相对日期","summary":"事件可以按先、后排列；昨天、今天、明天以当前参照日为准。上午和下午说的是时刻，不由活动名称决定。","reflection":"今天往后过一天，昨天和明天会怎样变？","batch":"B32"},"durationunit":{"topicId":"mt__N55B7u7HD","title":"用秒和分钟记一段","formal":"用时与时间单位","summary":"时长是从开始到结束经历多久。秒、分钟和小时是计量时长的单位；60秒是1分钟。这里的计时是模拟。","reflection":"计时开始晚了，记录会怎样？","batch":"B32"},"hoursday":{"topicId":"mt_2XDGT5tei1","title":"一小时和一天有多长","formal":"分钟、小时与天的关系","summary":"60分钟是1小时，24小时是1天。钟面每12小时转一轮，一天需要两轮；跨过60分钟要向小时进一。","reflection":"钟面只有12个数字，为什么一天有24小时？","batch":"B32"},"durationorder":{"topicId":"mt_6XCURuNwPw","title":"把花的时间排一排","formal":"时长的比较与排序","summary":"先确定每项活动用了多久，再按相同单位比较。先结束不一定用得更短，因为开始时刻可能不同。","reflection":"两人没有同时出发，只看谁先到能比快慢吗？","batch":"B32"},"durationwork":{"topicId":"mt_4emC463IyW","title":"从开始走到结束","formal":"经过时间的比较与计算","summary":"从开始时刻向前走到结束时刻，先走到整点再走余下的分钟。比较两段时长时，先统一单位再求差。","reflection":"10:15 到 11:00，为什么是45分钟？","batch":"B32"},"fractiontime":{"topicId":"mt_Jz9UuT8BXW","title":"一段时间分成几份","formal":"时间与事件的二分之一、四分之一和八分之一","summary":"先确定整个事件有多长，再平均分成相等的份。半小时是30分钟，一刻钟是15分钟；16分钟的八分之一是2分钟。","reflection":"半小时和半场比赛的“一半”，为什么不能只看同一个数字？","batch":"B32"},"elapsedtime":{"topicId":"mt_IL86kadLSS","title":"从这里走到几点","formal":"经过时间问题与时间轴","summary":"从开始时刻向前按分钟走；到60分钟时进一小时。也可以从开始走到结束，数一共经过多少分钟。","reflection":"14:15 走47分钟，为什么不会得到14:62？","batch":"B32"},"hourclock":{"topicId":"mt_0XxyaQLRhn","title":"整点和半点，指针在哪","formal":"整点与半点的钟面和数字时刻","summary":"长针走一圈是60分钟；短针在一小时内从一个数字慢慢走到下一个。半点时，短针位于两个小时数字中间。","reflection":"7:30时短针为什么不正对着7？","batch":"B32"},"fiveclock":{"topicId":"mt_HNOPGJYiRK","title":"长针每走一格，过了多久","formal":"每五分钟读写时刻","summary":"钟面上相邻两个数字之间是5分钟。长针在5上表示25分钟；过半小时后，也可以说离下一小时还差多少分钟。","reflection":"长针指着8，为什么不是8分钟？","batch":"B32"},"ampmclock":{"topicId":"mt_4m8BimI4G5","title":"同一个钟面，白天还是夜里","formal":"上午、下午与十二小时制","summary":"钟面每12小时重复一次，需要结合日期和上午、下午辨认。中午是12:00，午夜开启新的一天；只看指针不能知道是白天还是夜里。","reflection":"同样是8:45，为什么还需要知道是上午还是晚上？","batch":"B32"},"romanclock":{"topicId":"mt_5J2quSTspi","title":"换一套数字，钟还一样走","formal":"罗马数字钟面与十二、二十四小时制","summary":"I到XII表示钟面的1到12，IV也常写作IIII；分钟位置不变。下午1至11点对应13至23点；中午后的12点和午夜后的12点需要单独辨认。","reflection":"IV和IIII都在同一处时，长针走的分钟会改变吗？","batch":"B32"},"minuteclock":{"topicId":"mt_UNzojLkNdm","title":"再走几小格，读到分钟","formal":"精确到分钟的钟面和时长","summary":"先找长针经过的五分钟位置，再数余下的小格。短针看刚经过的小时，不看离哪个数字最近；秒和分钟的时长可以换成同一单位比较。","reflection":"7:43时短针更靠近8，为什么还读7？","batch":"B32"},"clockconvert":{"topicId":"mt_WfrE_4r-kY","title":"同一时刻，换种写法","formal":"十二小时与二十四小时时刻转换","summary":"同一时刻可以写成上午／下午的十二小时制，也可以写成00:00至23:59。下午1至11点加12；正午后的12点不加，午夜后的12点写成00点。","reflection":"15:45和下午3:45为什么是同一个时刻？","batch":"B32"},"timeconvert":{"topicId":"mt_2yas4Unc8o","title":"把小时换成分钟","formal":"时间单位与复名数换算","summary":"小时和分钟、分钟和秒都按60换；周和天按7换，年和月按12换。复名数需要把整份和剩余部分都保留。","reflection":"3小时25分钟为什么不是325分钟？","batch":"B32"},"quarterclock":{"topicId":"mt_MgsDabdnr1","title":"一刻过了，还是差一刻","formal":"一刻与差一刻的钟面","summary":"一刻是15分钟。3:15表示过了3点一刻；6:45距离7点还有一刻。长针转过四分之一圈时，短针也走过一小段。","reflection":"6:45为什么说差一刻到7点，而不是6点？","batch":"B32"},"weekmonth":{"topicId":"mt_bj1YCgNWUx","title":"星期和月份怎么接下去","formal":"星期、月份和年份的循环","summary":"一周有7天，一年有12个月；星期日以后接星期一，12月以后接下一年的1月。月份里的天数不都一样。","reflection":"星期日之后为什么还是星期一，而不是结束？","batch":"B32"},"calendarfacts":{"topicId":"mt_EXlmTURK_o","title":"月份的天数都一样吗","formal":"秒、月份天数与公历闰年","summary":"一分钟是60秒。公历各月天数不完全相同，平年365天、闰年366天；整百年需能被400整除才是闰年。","reflection":"为什么2024年有2月29日，而2100年没有？","batch":"B32"},"calendaruse":{"topicId":"mt_tVvZVWO5d6","title":"日历上的这一天","formal":"读取公历日期与日期间隔","summary":"先看年份、月份，再找日期所在的星期。算从一天到另一天相隔几天，从起点向后走，不额外把起点算一天。","reflection":"从6月3日到6月17日，为什么相隔14天？","batch":"B32"},"coinvalues":{"topicId":"mt_cPZwlUk8Nd","title":"一枚钱，值多少","formal":"英国货币面值","summary":"面值是写在钱上的价值，不由硬币的大小或数量决定。英国例子中100便士等于1英镑；不同币种不混算。","reflection":"一枚较小的钱为什么可能比一枚较大的更值钱？","batch":"B33"},"poundnotation":{"topicId":"mt_pbuhUQJjtt","title":"一笔钱，换个写法","formal":"英镑与便士的表示","summary":"同一笔英镑可以用英镑小数或便士数表示：£1.50就是150p。写法改变，金额不变。","reflection":"£1.50和150p为什么相等？","batch":"B33"},"coincombo":{"topicId":"mt_AF2BeFQwfX","title":"同样的数，几种摆法","formal":"等值货币组合","summary":"每一枚钱有自己的面值，把面值相加。不同数量和面值的硬币可以组合出相同总额。","reflection":"硬币枚数变多，金额一定变多吗？","batch":"B33"},"pennyshop":{"topicId":"mt_6J1wmCWf41","title":"买完，应该找回多少","formal":"便士的加减与找零","summary":"总价是各件价格合起来；找零是付款额与总价的差。钱不够时，差额表示还需要多少。","reflection":"怎样从价格往上数到付款额，找到应找的钱？","batch":"B33"},"poundchange":{"topicId":"mt_6_O6THdEDK","title":"几件东西，合起来","formal":"英镑与便士的总价和找零","summary":"先把同种钱的价格合起来，再与付款额比较。每100便士是1英镑，保留金额中的两位小数。","reflection":"£5减去£3.45时，为什么不能把45当作45英镑？","batch":"B33"},"modmoney":{"topicId":"mt_iQYPw8bMfN","title":"把故事里的数摆出来","formal":"测量与多步骤金额建模","summary":"先区分已知量、未知量和单位；条形图、数轴与算式都可表达关系。算完要回到故事，判断结果是总价还是找零。","reflection":"同一个数字，怎样知道它说的是总价还是找零？","batch":"B33"},"auscoins":{"topicId":"mt_FSLJbKkryb","title":"换个地方，钱长得不同","formal":"澳大利亚硬币与购买","summary":"澳大利亚元和分是另一套货币；100澳分等于1澳元。$2硬币比50c硬币小，但面值更大。这里的票币是标值示意。","reflection":"硬币大小和面值为什么不能画等号？","batch":"B33"},"austrans":{"topicId":"mt_8cs4YPkp23","title":"把几次购买接起来","formal":"澳元交易与找零","summary":"同一种货币的商品价格可以合计；相同价格的多个商品可重复相加。找零是付出与总价的差。","reflection":"同价的三个苹果，为什么可以把同一个价格加三次？","batch":"B33"},"dollarcents":{"topicId":"mt_9L5qyBYmg-","title":"元与分，还是同一笔钱","formal":"澳元与澳分的换写和等值","summary":"100澳分是1澳元；$2.70与270c表示同一笔澳元。不同面值可组成相同金额，找零仍由付款减总价。","reflection":"$2.70为什么不是270澳元？","batch":"B33"},"usmoney":{"topicId":"mt_3tz3Otap5j","title":"再换一种钱，先看标记","formal":"美元和美分情境","summary":"美国例子里，100美分是1美元。币值看面值；先合计，再根据付款和价格决定总价或找零。","reflection":"美元和澳元都用$时，为什么不能直接混在一起？","batch":"B33"},"moneycalc":{"topicId":"mt_FVVSQR9vGg","title":"先猜大概，再让机器算","formal":"金额计算器与估计核对","summary":"先估一个范围，再输入算式，把显示结果读成对应币种的金额。选择心算或计算器是一种策略，屏幕不能证明心里怎样算。","reflection":"计算器显示3.55时，为什么还要回头看它代表什么？","batch":"B33"},"measuremoney":{"topicId":"mt_mFJ-2ZF6Tk","title":"单位不同，怎样一起比","formal":"测量估计、质量比较与金额计算","summary":"先估计再测量，比较不同单位先换成同一单位；金额相加时也要保留同一币种和单位。","reflection":"1.5 kg和1200 g，为什么不能只比较1.5和1200？","batch":"B33"},"roughmoney":{"topicId":"mt_5bmrA-0pBi","title":"先看差不多，再算准","formal":"金额估计与澳大利亚现金取整示例","summary":"估算用附近好算的数判断结果是否合理；精确计算与估算不同。这里的澳大利亚现金总额按题目给定的5分规则取整。","reflection":"估算约15元，为什么精确答案不一定正好是15元？","batch":"B33"},"budgetchoices":{"topicId":"mt_Qe2PsFmSAH","title":"有限的钱，怎样选","formal":"预算与单位价格","summary":"先选出需要的东西，合计后与预算比较；不同选择都可能可行。比较包装价格要换成同样数量的单价。","reflection":"标价更低的一包，为什么不一定每千克更便宜？","batch":"B33"},"discounts":{"topicId":"mt_oMkQQ2O-ML","title":"打折、加税和欠了多少","formal":"折扣、指定税率与负余额","summary":"折扣按原价计算；澳大利亚示例的10% GST按税前价计算，已含税的价格不再加一次。负余额在零的另一侧。","reflection":"打九折和减去9元，为什么不一定一样？","batch":"B33"},"moneysheet":{"topicId":"mt_mMDpLugX2X","title":"让表格替你跟着算","formal":"金额表格、折扣与税的公式","summary":"表格公式引用已有单元格；更改价格时需重新计算。折扣和税的百分比要作用在正确的基数上。","reflection":"把税前价格换一换，公式和结果会怎样变化？","batch":"B33"},"structure34":{"topicId":"mt_FAXjFkgG6X","title":"看见没有变的部分","formal":"数位、运算与图形结构","summary":"加整百时个位和十位不变；跨过整千时千位也会变化。乘法阵列转向后总数不变，图形可以按边和角的性质分类。","reflection":"变了方向或单位，哪些关系仍然不变？","batch":"B34"},"repeat34":{"topicId":"mt_WXW0hjNhph","title":"一小段，怎样反复出现","formal":"重复图案与重复单元","summary":"重复图案由一个片段按相同次序接下去。要找最短重复片段，也可以自己决定片段并继续。有限开头可能符合不同规则。","reflection":"怎样知道自己圈出的是更短的一组，而不只是更长的一段？","batch":"B34"},"linear34":{"topicId":"mt_hBZwbst0ow","title":"每一步都多同样的量","formal":"等差数列与逐项规则","summary":"从起点出发，每一步加同一个数或减同一个数；负数和小数也能沿同一规则继续。要找远处一项，可以从位置直接计算。","reflection":"第10项要走几次，为什么不是10次？","batch":"B34"},"paired34":{"topicId":"mt_fxPtngwUfz","title":"两条路，一起往前","formal":"对应数列与坐标","summary":"两条数列从0开始，分别每次加3和加6，同一位置上的第二个数是第一个的两倍。换起点以后要重新检查；一对数可以放到坐标图上。","reflection":"每一步是两倍，起点不一样时对应项还会一直是两倍吗？","batch":"B34"},"rules34":{"topicId":"mt_yXO7lQ9Yn7","title":"一条规则，走到远处","formal":"逐项规则与按位置生成","summary":"逐项规则从前一项走到下一项；按位置的规则从第几项直接算出它。固定差、固定倍数与其他变化需要分开看。","reflection":"只看到开头几个数，怎样知道下一项一定是什么？","batch":"B34"},"notice34":{"topicId":"mt_uG2mjHFOlO","title":"换个顺序，数量变了吗","formal":"加法结构、十和图案","summary":"同一批东西交换两组的次序，总数不变；十几可以看成一个十和几个一。观察重复的次序才能预测下一处。","reflection":"把两组交换位置，为什么数量不需要重新出现？","batch":"B34"},"general34":{"topicId":"mt_fZTn0W_iZR","title":"借熟悉的关系走一步","formal":"接近双倍、十位与变化规则","summary":"6+7可以看成6+6再加1。两位数减10时，十位减少一；按5递增时个位怎样变化要看起点。","reflection":"每次加5为什么有时是0和5轮流，有时却不是？","batch":"B34"},"tables34":{"topicId":"mt_2jbUekyTu4","title":"把大的乘法拆成两块","formal":"倍数、阵列分解与增长","summary":"4的倍数都能两两配对；8×7可以分成8×5与8×2。重复加50可以向后走，也可以记录每一步。","reflection":"把阵列切开后，为什么两块都仍然有8份？","batch":"B34"},"reason34":{"topicId":"mt_iyovKgZC1q","title":"从几个例子，到一条说法","formal":"多边形、数列和分数的概括","summary":"凸n边形从一个顶点可分成n−2个三角形，内角和为(n−2)×180°。除以非零n可写成a/n；约分后分母不一定还是n。有限例子不是一般证明。","reflection":"6÷3能写成6/3，又等于2；分母为什么可以改变？","batch":"B34"},"shapeseq34":{"topicId":"mt_A-FyLLLLzy","title":"走着走着，藏着什么","formal":"数列与图案中的附加特征","summary":"从1开始每次加3，奇偶交替；从2开始每次加4始终为偶数。先说清产生每一项的规则，再观察隐藏的特征。","reflection":"规则只说加4，为什么结果一直是偶数？","batch":"B34"},"trace34":{"topicId":"mt_zQfWqImxva","title":"让每个数走一条路","formal":"顺序、判断与停止条件","summary":"规则要说清起点、判断、下一步与何时停止。偶数减半、奇数加1的有限示例能追踪每一步；运行过几次并不证明所有输入都终止。","reflection":"数字恰好是50时，会走“大于50”那一边吗？","batch":"B34"},"generate34":{"topicId":"mt_QeKWt4BZn3","title":"让规则自己长出一串数","formal":"生成数列的步骤与边界","summary":"从3翻倍直到结果超过100，会保留第一次超过100的数。不断加7并只留小于80的数，则应在下一次到80或更多之前停下。","reflection":"“超过后停”与“不能到达之前停”，末尾会有什么不同？","batch":"B34"},"design34":{"topicId":"mt_nx4a3kH-59","title":"先安排步骤，再看看结果","formal":"分支、重复与可检查的算法","summary":"一个数同时符合两个条件时，必须留出两者都符合的类别。重复“乘2再加1”产生奇数；实际解释和一般证明需另行表达。","reflection":"先检查3的倍数，会把同时是3和5倍数的15放到哪里？","batch":"B34"},"pairs34":{"topicId":"mt_gu0NPDvlhY","title":"怎样保证一对也不漏","formal":"有序列举与乘法原理","summary":"固定第一种选择，把第二种逐个配完；每个格子是一种不同组合。3种前菜和4种主菜能组成3×4种搭配。","reflection":"把两种选择换个顺序，会不会变成新的搭配？","batch":"B34"},"missing35":{"topicId":"mt_ezc2m_0dzN","title":"从这里走到那里，还差多少","formal":"加法中的未知数与减法","summary":"8加几到10，与10减8是在找同一个缺少的部分。可以从已知部分向目标走，再把找到的数放回原来的关系检查。","reflection":"8＋□＝10和10−8＝□，为什么找到的是同一段？","batch":"B35"},"bigmissing35":{"topicId":"mt_XuHmIn2xje","title":"空着一格，也能找到路","formal":"较大数与多步问题中的未知数","summary":"245加135等于380；可以按整百、整十和一逐步走，也可以用减法寻找缺少的量。原式代回检查，数值大小和方法选择是两回事。","reflection":"换个起点或空格的位置，怎样判断是在找哪一部分？","batch":"B35"},"twostep35":{"topicId":"mt_anAe11HAEH","title":"先做了两件事，怎么倒回来","formal":"两步问题与一元方程","summary":"把同一个数取3份再加5得到26，可以写成3x＋5＝26。先去掉5，再把剩下的量平分三份；最后把找到的数代回。","reflection":"为什么要先处理加上的5，而不是先把26除以3？","batch":"B35"},"twounknown35":{"topicId":"mt_YFS7JFk64p","title":"一个关系，有多少对伙伴","formal":"二元一次等式与有范围的解","summary":"一个关系可能有很多对数。固定第一个数、依次换值并算伙伴，可以在明确的整数范围内检查是否有遗漏。交换位置是否新的一对，取决于两列代表的量。","reflection":"如果不限制数的范围，还能把所有伙伴写完吗？","batch":"B35"},"equations35":{"topicId":"mt_QhFEDyIwSO","title":"让两边一起变化","formal":"一元一次方程与等量变换","summary":"等号两边表示同值。对两边做相同加减，或同乘同除非零数，可以保持等价；找到未知数后代回原式。答案也可能是负数或分数。","reflection":"5−x＝6为什么可以得到负数，而不是先把5和6交换？","batch":"B35"},"writing35":{"topicId":"mt_i9rJbuFO3p","title":"把一件事写成一个关系","formal":"用字母列方程","summary":"字母表示一个数，不是物品的名字。先分清数量、先后动作和总量，再写等式；把数代回情境检查。","reflection":"“先加5再翻倍”和“先翻倍再加5”，为什么不一样？","batch":"B35"},"notation35":{"topicId":"mt_KwdjWEmMNo","title":"字母旁边的数字在做什么","formal":"代数记号与运算顺序","summary":"3x表示3乘x，x²表示x乘x；x/2表示x除以2。括号把先做的部分圈在一起，代入一个具体数能检查读法。","reflection":"当x＝3时，2x与x²各是多少？","batch":"B35"},"model35":{"topicId":"mt_z5iwdZyeDr","title":"同一个关系，换成表和图","formal":"从情境到代数、数表和图像","summary":"先说清字母代表什么数量，再按同一规则生成数对、放到图上。图中的点表示一对同时对应的数；坐标和单位不能随意交换。","reflection":"一个点的位置，怎样对应故事里的两个数量？","batch":"B35"},"words35":{"topicId":"mt_g_fkAqmz72","title":"给刚才用到的东西起名字","formal":"代数式、方程、不等式与项","summary":"代数式表示一个值；方程和不等式分别用等号或不等号陈述关系。项、系数和因子分别描述表达式里的不同角色。","reflection":"2x＋3与2x＋3＝7，为什么不是同一种写法？","batch":"B35"},"nth35":{"topicId":"mt_HRKzwEQJgO","title":"不用一项项走，也能到远处","formal":"等差数列的第 n 项","summary":"3、7、11、15每次加4；第n项为4n−1，n从1开始。已知位置可直接求数；想判断某个数是不是一项，还要检查对应位置是否为正整数。","reflection":"每次加4，为什么第n项不是4n＋3？","batch":"B35"},"terms35":{"topicId":"mt_nNNVrLqPW3","title":"哪些能合在一起","formal":"同类项与合并","summary":"只有变量及其指数相同的项可以合并，符号随项一起保留。x、x²、y与常数各自有不同结构；结果仍可能包含好几项。","reflection":"3x＋2y为什么不能直接写成5xy？","batch":"B35"},"expand35":{"topicId":"mt_FX4a2Q8XXN","title":"一份里的每部分，都要带上","formal":"单括号展开与分配律","summary":"括号外的一份乘数要作用于括号里的每一项。负号也参与乘法；展开后再合并同类项。符号表中的负数不表示物理负面积。","reflection":"−2(x−3)为什么会有正6？","batch":"B35"},"factor35":{"topicId":"mt_uESbzWCZIq","title":"拆开以后，能不能再收起来","formal":"提取公因式与展开检验","summary":"共同因子可以从各项中提出，例如6x＋9＝3(2x＋3)。要把每一项都除以提出的因子，再乘回去检查；本活动只处理给定的有限例子。","reflection":"为什么把2提出6x＋9并不能让括号里的两项都保持整数？","batch":"B35"},"double35":{"topicId":"mt_KhS7K1Mgrw","title":"两个括号，怎样一项都不漏","formal":"双括号展开与合并","summary":"每个括号中的每一项都要与另一边的每一项相乘。四格表记录四个乘积，符号一起计算，最后再合并同类项。","reflection":"(x＋3)²为什么不能只写成x²＋9？","batch":"B35"},"systems35":{"topicId":"mt_mqgu72aCMz","title":"哪一个位置，两条线都经过","formal":"二元一次方程组的图像与代入","summary":"两条不同直线相交时，交点满足两条等式。平行直线没有共同点，重合直线有无穷多个；图上读出的近似位置还要代回两式。","reflection":"只落在一条线上，为什么还不能说它满足两条关系？","batch":"B35"},"formula36":{"topicId":"mt_Jvg8X0N5u0","title":"换一个尺寸，会变成多少","formal":"简单公式与代入","summary":"长方形一圈是长和宽的和再乘2，三角形里面是底乘对应垂直高度再除以2。先看图中的量和单位，再把数放进关系。","reflection":"底和斜边看起来都像边，为什么三角形面积要配垂直高度？","batch":"B36"},"coords36":{"topicId":"mt_hVpGOEz2kG","title":"在四个方向里找位置","formal":"四象限坐标","summary":"一个位置用两个数表示：先看横向x，再看纵向y。正负表示方向，数轴上的点不属于任何象限；半格也有自己的位置。","reflection":"(−2,3)和(3,−2)为什么不是同一个点？","batch":"B36"},"substitute36":{"topicId":"mt_vHzVa3SURC","title":"把一个数放进关系","formal":"代数式与公式的数值代入","summary":"字母代表数；代入负数时用括号保留符号。先算平方，再乘除，最后加减；0、负数和分数也可以试。","reflection":"(−2)²为什么和−2²不一样？","batch":"B36"},"linear36":{"topicId":"mt_WBdHkc2HTf","title":"改变一个数，线会怎样","formal":"一次函数图像、斜率与截距","summary":"y＝mx＋c中，m控制每往右一单位时y的变化，c表示x＝0时的值。线位置更高不代表变化更快；负斜率表示向右看时下降。","reflection":"两条线中位置较高的那条，为什么不一定前进得更快？","batch":"B36"},"plot36":{"topicId":"mt_-3udyo6VyB","title":"点连起来，藏着什么变化","formal":"一次函数的数表、图像与斜率","summary":"先用同一规则生成数对，再把点放进坐标图；斜率是纵向变化除以横向变化。2x＋3y＝12可以改写为y＝4−2x/3。","reflection":"只看线画得陡不陡，为什么还要注意两个轴各表示多少？","batch":"B36"},"rearrange36":{"topicId":"mt_3qrCtdoVAU","title":"把另一个量留在一边","formal":"公式变形与定义域","summary":"公式中的不同量可以互相寻找。对两边做保持等价的操作，注意除数不能为零；平方反推时可能有两个结果。","reflection":"y＝x²而y＝9，为什么x可能是3，也可能是−3？","batch":"B36"},"quadratic36":{"topicId":"mt_GZuoYaDdWd","title":"为什么它弯了回来","formal":"二次函数图像与零点","summary":"负数和正数平方后可能得到相同的值。y＝x²−4的左右两侧对应，曲线与横轴交于−2和2；平方项系数为负时曲线向下开口。","reflection":"从左到右逐项增加x时，每一步变化的幅度为什么先变小再变大？","batch":"B36"},"pctNames37":{"topicId":"mt_4ubP_RMg9o","title":"一份量，三种名字","formal":"百分数、分数与小数的对应","summary":"20%是每100份中的20份，也等于1/5和0.2；折扣部分与剩下的价格不同。","reflection":"同样写20%，换了整体，拿到的数量为什么会变化？","batch":"B37"},"pctWhole37":{"topicId":"mt_ZM9mhHsyYZ","title":"把整个分成一百份","formal":"百分数与整体","summary":"一个整体分成100等份，35份就是35%；50%是整个的一半，100%是整个。","reflection":"50%一定是50个东西吗？","batch":"B37"},"pctIdeas37":{"topicId":"mt_ESgc4YBw-a","title":"两种颜色，怎样保持味道","formal":"比、比例与缩放倍数","summary":"比描述两个量怎样对应；两组比相等时，关系保持。相似放大让对应长度乘同一个倍数。","reflection":"两种颜色都多加一杯，味道一定不变吗？","batch":"B37"},"pctCalculate37":{"topicId":"mt_PNSyfH56eQ","title":"先找容易的一块","formal":"百分数的分拆计算","summary":"10%是把整个分成十份的一份，5%是它的一半；15%可以将这两块接起来。比较折扣要先看各自原价。","reflection":"15%和10%相比，为什么省下的钱不一定更多？","batch":"B37"},"pctFraction37":{"topicId":"mt_ALUrJpY0cZ","title":"超过整个，也能用百分数","formal":"百分数、数量关系与变化","summary":"分数、小数和百分数可以说同一关系；150%是一份半。变化率与变化后的总量要分清，比较时先确定整体。","reflection":"150%为什么不等于比原来多150%？","batch":"B37"},"pctChange37":{"topicId":"mt_iEXqN48w3x","title":"涨了、降了，再倒着找","formal":"百分比增减、反求与单利","summary":"增加15%得到原来的115%；打八折后的金额是原来的80%。简单利息每年都以原本金为基准，不把利息加回本金再算。","reflection":"先减少20%再增加20%，为什么不一定回到原来？","batch":"B37"},"ratioProblem37":{"topicId":"mt_h0gJcSuwdL","title":"两种东西一起添","formal":"比的对应与倍数","summary":"相同配比可以把每种数量都乘同一个数；两边各加同一个数通常会改变配比。","reflection":"3份红、5份蓝；两种都加2份，还是同一味道吗？","batch":"B37"},"ratioShare37":{"topicId":"mt_FnUJMXPUZX","title":"不是每人一样多，怎样公平分","formal":"按比分配与整体的分数","summary":"先把比里的份数加起来，整个平均分成这些小份，再按各人份数拿走。","reflection":"2:3里的2，为什么是整个的2/5？","batch":"B37"},"ratioDivide37":{"topicId":"mt_nOCPx5qw0Z","title":"先找一份，再分给每个人","formal":"两项及三项的按比分配","summary":"按比把总量分给各部分，先找同样大小的一份。把实际数量写成比时，也可以同时除以共同因数。","reflection":"把10:14写成5:7，为什么没有改变两人的关系？","batch":"B37"},"fractionOf37":{"topicId":"mt_xAf2bu9wYK","title":"这段占另一段的多少","formal":"一个量占另一个量的几分之几","summary":"先换成相同单位，再用要比较的量除以作为整体的量。前者比后者大时，结果可以大于1。","reflection":"45分钟占2小时多少，为什么不能直接写45/2？","batch":"B37"},"rateWords37":{"topicId":"mt_ATYLKt0je-","title":"一起变，还是反着变","formal":"正比例、反比例与复合单位","summary":"直接比例中两个量的商保持；在给定非零范围内，反比例的积保持。速度、单价和密度都要说明每一单位对应什么。","reflection":"人数增加时，完成时间一定减少吗？还需要什么条件？","batch":"B37"},"ratioNotation37":{"topicId":"mt_XWSGuFW7It","title":"比的前后，不能随便换","formal":"比的顺序、化简与部分占整体","summary":"12:8和3:2说的是相同的对应关系；3:2分成五份，前者占3/5。含小数或分数的比也可同时乘同一非零数化简。","reflection":"3:2里的3/2和3/5，各自拿谁作整体？","batch":"B37"},"proportion37":{"topicId":"mt_5mIcmKRCgA","title":"两个量怎样一起变化","formal":"正比例、反比例与图像","summary":"正比例可以写成y=kx，图线经过原点；反比例在非零范围满足xy=k。现实故事还要说明数量和单位怎样约定。","reflection":"一个量翻倍，另一个量也翻倍，和减半有什么不同？","batch":"B37"},"ratioLink37":{"topicId":"mt_yK51ZnKA8m","title":"同一个关系，换三种看法","formal":"比、分数与函数的联系","summary":"2:5可以比较红与蓝，也可以说红是蓝的2/5；红占全部则是2/7。表示成函数时要先说清谁是输入、谁是输出。","reflection":"为什么2:5不等于红色占全部的2/5？","batch":"B37"},"recipeScale37":{"topicId":"mt_ZOJ6EbdPOb","title":"人数和材料一起变","formal":"配方、单价与几何缩放","summary":"配方、价格和相似图形都可以在给定条件下按倍数缩放；先找一份或单位量，再换成想要的数量。","reflection":"人数变成一份半，材料该加半杯，还是变成一份半？","batch":"B37"},"similar37":{"topicId":"mt_2OtRUM_0zW","title":"图形放大，什么没变","formal":"相似图形与比例因子","summary":"相似放大或缩小时，对应边乘同一个倍数，对应角不变。每条边都加相同长度通常不能保持形状。","reflection":"每边都加2与每边都变成2倍，有什么不同？","batch":"B37"},"scaleMap37":{"topicId":"mt_1badik7iKJ","title":"图上的一小段，现实有多长","formal":"比例尺、地图与单位","summary":"比例尺的两边要先用相同单位。图上1厘米对应实际50厘米时，改成1:100的图，图上同一段会变短。","reflection":"同一个房间，图上变短了，真实墙变短了吗？","batch":"B37"},"scaleArea37":{"topicId":"mt_CUJr8L5_Wn","title":"边放大了，里面变多少","formal":"比例图中的面积","summary":"长度按k倍变化时，两个方向都变化，面积按k²倍变化。先将长度换到同样单位，再求实际面积。","reflection":"边长变成3倍，为什么里面不是只变3倍？","batch":"B37"},"rateUnit37":{"topicId":"mt_kLQOzZYrd5","title":"一份、一小时和一个小方块","formal":"速度、单价与密度","summary":"速度是距离除以时间，单价是价格除以数量，密度是质量除以体积；比较前要把单位对齐。","reflection":"便宜的一包，为什么不一定每千克更便宜？","batch":"B37"},"proportionGraph37":{"topicId":"mt_FspV_imUGK","title":"把一对一对的变化放上图","formal":"正比例的数表与图像","summary":"相同的单位率产生一组数对；零份对应零总量，正比例图线经过原点。图中两个轴要说明各代表什么。","reflection":"有些直线经过原点，有些没有，差别可能是什么？","batch":"B37"},"convertUnits37":{"topicId":"mt_tpT9brpI6D","title":"单位改变，量还一样","formal":"面积、时间与体积单位换算","summary":"长度单位改变时，面积需要两个方向一起换。1平方米有10000平方厘米；1升等于1000立方厘米，1小时等于60分钟。","reflection":"1米是100厘米，为什么1平方米不是100平方厘米？","batch":"B37"},"show38":{"topicId":"mt_nyK25mNOeR","title":"让别人看见你怎么想","formal":"展示解题过程","summary":"数字能告诉别人结果，圆片和动作还能展示它是怎么来的。看别人的方法时，可以指出具体哪一步与原来的数量对不上。","reflection":"如果对方只说出答案，你还想看见什么？","batch":"B38"},"because38":{"topicId":"mt_a3dov8CZkq","title":"为什么能这样说","formal":"依据、错误分析与推理链","summary":"比较分数时要说清同一个整体。拆开一捆十只改变表示，不改变总量。6个8可以从6个10中拿走6个2得到。","reflection":"你说的每一步，能从前面哪一件事得到？","batch":"B38"},"argument38":{"topicId":"mt_j5YqQnN6xe","title":"找一个能推翻它的例子","formal":"数学论证、反例与推理链","summary":"给出的条件和已知关系可以连成推理；一个符合条件却与“总是”相反的例子，可以推翻这句“总是”。几个符合的例子不能证明所有情况。","reflection":"如果把“总会变大”改成“总不会变小”，你刚才的例子还管用吗？","batch":"B38"},"pattern39":{"topicId":"mt_RFeVlw0QvX","title":"能不能猜到下一站","formal":"重复变化与数表规律","summary":"每次加2，起点是偶数就仍落在偶数，起点是奇数就仍落在奇数。百数表每行十个时，加10通常到下一行同列；加1到了行末要接到下一行开头。","reflection":"如果不是从偶数开始，每次加2还会落在偶数上吗？","batch":"B39"},"structure39":{"topicId":"mt__Itf4aQZUj","title":"把大问题拆成熟悉的部分","formal":"分配律、位值与图形包含","summary":"7×13可以拆成7×10与7×3；每部分都保留7。乘10时每个数字代表的单位变成十倍，小数点不移动。正方形有四个直角，所以也是长方形。","reflection":"把13拆开后，为什么两部分都要乘7？","batch":"B39"},"strategy39":{"topicId":"mt_mQcWGh02no","title":"遇到问题，先挑条路","formal":"计算与测量策略的选择","summary":"同一道计算可以用数的关系、写下步骤或计算器；方法是否顺手取决于数字、工具和自己。长距离可以用更长的尺，也可分段，但每段要接好。","reflection":"同一个问题，换一种方法会让什么更容易看见？","batch":"B39"},"tools39":{"topicId":"mt_d-WZC2OyMB","title":"选个工具，再用另一种检查","formal":"计算、分数表示与面积核对","summary":"25×4可以利用25的4份；167×3也可以有多种方法。分数条和数轴能表示同一整体，方格数与长乘宽可以相互核对。","reflection":"你会用哪一种表示让别人看见两个分数的大小？","batch":"B39"},"representations39":{"topicId":"mt_IwEOCN6bL1","title":"先看大概，再找更清楚的表示","formal":"策略选择、角度核对与分数基准","summary":"估角后可以对齐量角器再测量。用一半比较分数时，若两个都在同一边，单凭一半不能排出先后；换共同小份可以继续比较。","reflection":"两个分数都比一半大，就能知道谁更大吗？","batch":"B39"},"graph39":{"topicId":"mt_Yw27nweoTj","title":"沿着线，读出一个大概","formal":"图像读数、交点与情境解释","summary":"读图先看横纵坐标和每格大小。曲线与横轴相交的横坐标是对应高度为0的解；两条线相交时，两边的值相同。图上读数通常是近似值。","reflection":"只找到一个交点，能确定另一边没有吗？","batch":"B39"},"calculator39":{"topicId":"mt_ish_uH8vZe","title":"计算器给出结果，还要看什么","formal":"计算器输入、估计与核对","summary":"先估计数量级，再检查计算器里的数字、运算符与结果。1468＋2975＋813＝5256；83×5＝415，4150离约400很远，应重新检查。估计接近也不能证明精确无误。","reflection":"如果计算器显示的数不合理，可能是哪一步出了问题？","batch":"B39"},"tooladv39":{"topicId":"mt_ZJC7JnnPCu","title":"问题变大，工具要不要换","formal":"长除法、坐标核对与体积公式","summary":"数量多时可以考虑公式、分层或逐项计数；选择取决于问题和自己。4752÷13＝365余7；坐标图能把平移前后的位置放在同一张图上。","reflection":"数方块和用公式结果不同时，你会怎样重新检查？","batch":"B39"},"words38":{"topicId":"mt_lMz9nAs7VO","title":"说清多少、形状和位置","formal":"比较、形状与位置词","summary":"比较时说清谁比谁多；数直边与角点可以描述形状；说位置时要让对方知道参照物。","reflection":"换个观察位置，左和右会不会改变？","batch":"B38"},"communicate38":{"topicId":"mt_TMoHjMhRS2","title":"一句话少了什么","formal":"等号、单位与几何词","summary":"等号两边表示相同的量，答案可以在左边。测量结果要带单位；面、棱和顶点是立体上不同的部分。","reflection":"只写一个12，别人知道你量的是长度还是面积吗？","batch":"B38"},"precise38":{"topicId":"mt_mywsN77hGZ","title":"换个说法，还是同一个量","formal":"分数、面积单位与时刻","summary":"四分之三说的是同一整体平均分四份取三份。面积用平方单位；下午3:45与15:45是同一个时刻的不同写法。","reflection":"如果只写3:45，别人能知道是上午还是下午吗？","batch":"B38"},"term38":{"topicId":"mt_xfwv0M83mJ","title":"这些名字，指的是谁","formal":"因数、倍数、面积体积单位与平方","summary":"4×6＝24时，4和6是24的因数，24是4和6的倍数。铺平面用平方单位，填空间用立方单位；5²表示5×5。","reflection":"一个数可以同时是另一个数的倍数，又是第三个数的因数吗？","batch":"B38"},"advancedWords38":{"topicId":"mt_3rTIyJDw7-","title":"圆上的线与算式的名字","formal":"半径、直径、周长及表达式、等式和公式","summary":"半径连接圆心与圆周，直径经过圆心并连接圆周两端；周长是圆边的长度。等式表示相等，公式则说明可反复使用的关系。","reflection":"看见等号时，怎样判断这条关系是在说明什么？","batch":"B38"},"tools38":{"topicId":"mt_20WfHhnL39","title":"先挑工具，再试一试","formal":"选择表示工具并组织数量","summary":"同一个数量可以用圆片、十格或条形表示。工具有没有帮忙，要看它是否让当前关系更容易看清。","reflection":"这次你选的画法，帮你看清了什么？","batch":"B38"},"sense38":{"topicId":"mt_WkKkb7W9Qd","title":"先看它究竟在问什么","formal":"理解问题、表示和检查","summary":"先分清已经知道的与想找的，再用图或动作表示。得到结果后，把它放回故事里检查是否说得通。","reflection":"如果故事里多了一条没用的信息，你会怎样处理？","batch":"B38"},"story38":{"topicId":"mt_IM1G_7QzTa","title":"故事和图，怎样互相翻译","formal":"生活情境、动作与运算","summary":"东西合起来可以用加法表示，拿走可以用减法表示。图和算式需要和故事中的动作及数量一一对应。","reflection":"同一张图，能不能讲出两个不同但都说得通的故事？","batch":"B38"},"objects38":{"topicId":"mt_fLOkq-HfPB","title":"让图替故事说话","formal":"用对象和图表示生活问题","summary":"用圆片或图表示故事时，每一部分都要对应故事中的量；算式、图和问题要说同一件事。","reflection":"如果把图里的某一堆拿走，故事里发生了什么？","batch":"B38"},"lifemath38":{"topicId":"mt_f67qGDhyfi","title":"把算出来的数送回故事","formal":"长度、钱与多步情境建模","summary":"同一个数放回故事时要说清它代表什么、使用什么单位。画出各部分有助于区分已知、变化和要找的量。","reflection":"27是什么意思？它是剪掉的长度，还是剩下的长度？","batch":"B38"},"model38":{"topicId":"mt_8xVHooT4aI","title":"食谱、房间和折扣","formal":"配方、比例图、面积与折扣建模","summary":"先把现实里的量变成数学关系，再把结果带回原来的单位。配方按份数缩放，房间面积看两个方向，折扣先找原价。","reflection":"如果人数加一半，材料是多半份，还是每样只多半克？","batch":"B38"},"modelChoice38":{"topicId":"mt_yqZiX6vS7D","title":"同一个问题，选哪张图","formal":"比例、体积与测量精度建模","summary":"比例、体积和测量适合不同的表示；结果要带回情境。取整到哪里取决于测量方法和实际需要。","reflection":"装人的车数和测量一根绳子的长度，能用相同的取整方式吗？","batch":"B38"},"plan38":{"topicId":"mt_O_UOTiMvT_","title":"先定方向，再看结果","formal":"已知未知、策略与合理性检查","summary":"先找到已知量和想求的量，再尝试一种办法；算完可以换一种方式或用估计检查。","reflection":"一个结果看起来差不多，能保证它一定准确吗？","batch":"B38"},"multi38":{"topicId":"mt_RKeheOL9uo","title":"两步之间，不要丢掉中间量","formal":"两步问题、估计与反向检查","summary":"把一件事拆成小问题时，中间结果也要说明它代表什么。估计能发现明显不合理的量级，反向计算可以再核对。","reflection":"估计接近结果，与结果精确无误，是同一回事吗？","batch":"B38"},"multiShape38":{"topicId":"mt_SmghasIvbT","title":"图、算式和大概范围","formal":"多步计划、周长与分数估计","summary":"先把故事中的关系摆清，再决定用图还是算式。周长看外边一圈；分数部分可以与一半和整个比较。","reflection":"20的3/5为什么应当比10大？","batch":"B38"},"complex38":{"topicId":"mt_GpltXPoaoc","title":"先估一估，再走几步","formal":"多步换单位、数量级与百分数边界","summary":"单位换好后才能把量接起来。估计能帮忙发现量级错误；部分占整体的百分比要看问题是否允许重复或超过整体。","reflection":"什么时候超过100%不可能，什么时候又可能？","batch":"B38"},"advancedPlan38":{"topicId":"mt_FieL-vVTI_","title":"先认清谁是未知，再决定顺序","formal":"比例、方程与小数除法估计","summary":"按比分配先找总份数与一份；用字母前先说明它代表什么。估计小数除法时，先用容易比较的附近数判断范围。","reflection":"如果换了未知量的位置，原来的第一步还合适吗？","batch":"B38"}};
